input.command:
cd /tmp && cat > debug_mark.awk << 'EOF'
function lvl(s,   c) {
  c = 0
  while (substr(s, c + 1, 1) == "#") c++
  if (c < 1 || c > 6 || substr(s, c + 1, 1) != " ") return 0
  return c
}
function htext(s,   t) { t = substr(s, lvl(s) + 2); sub(/[ \t\r]+$/, "", t); return t }
BEGIN { FENCE = "\140\140\140"; PFX = "Replace: "; WPFX = "Withdraw: " }
{ L[++n] = $0 }
END {
  for (i = 1; i <= n; i++) C[i] = L[i]
  m = n
  # compute H via fence tracking
  f = 0
  for (i = 1; i <= m; i++) {
    if (substr(C[i], 1, 3) == FENCE) { f = !f; H[i] = 0; continue }
    H[i] = f ? 0 : lvl(C[i])
  }
  nb = 0; i = 1
  while (i <= m) {
    if (H[i] == 2 && substr(htext(C[i]), 1, length(WPFX)) == WPFX) {
      i += 1
    } else if (H[i] == 2 && substr(htext(C[i]), 1, length(PFX)) == PFX) {
      j = i + 1; h = (j <= m) ? H[j] : 0
      k = (j <= m && h != 1) ? j + 1 : j
      while (k <= m && !(H[k] >= 1 && H[k] <= 2)) k++
      i = k
    } else { B[++nb] = C[i]; Borig[nb]=i; i++ }
  }
  for (i = 1; i <= nb; i++) {
    bl = lvl(B[i])
    if (bl > 0) print "B-line(orig="Borig[i]"): " B[i]
  }
}
EOF
awk -f debug_mark.awk /tmp/concat_all.txt | grep -n "Ground Truths"

\
F=".first-principles/analysis-20261015T032239Z.md"; R="${F%/*}/report-${F##*/analysis-}"; { printf '# '; cat <<'FP_EOF'
Molten-Salt Thermal Storage Round-Trip Efficiency Claim
FP_EOF
printf '\n*First-principles analysis · %s*\n\n' "$(date -u '+%-d %B %Y')"
printf '*Read with: [How to read this analysis]''(HOW-TO-READ.md) · [Working file]''(%s) · [All files]''(INDEX.md)*\n\n' "${F##*/}"; awk '
/^```/ { f = !f }
!f && /^## Appendix — process output$/ { exit }
!f && /^\*\*Disclosed:\*\*/ { skip = 1 }
skip && /^#/ { skip = 0 }
skip { if ($0 == "") skip = 0; next }
!f && /^\*\*Pre-check:\*\*/ { next }
!f && /^## Answer$/ { $0 = "## Executive Summary" }
!f && (/^#/ || /^\*\*/) && prev != "" { print "" }
{ print; prev = $0 }' "$F" | cat -s; } > "$R" && echo "$R"

\
R=".first-principles/report-20261015T032239Z.md"
B="${R##*/}"; B="${B%.md}"
TL=""; [ -s "${R%.md}-fig-trace.svg" ] && TL="![Evidence trace: ground truths, chains and the conclusion]""($B-fig-trace.svg)"
VL=""; [ -s "${R%.md}-fig-verdicts.svg" ] && VL="![Assumption verdict matrix: assumption types against verdicts]""($B-fig-verdicts.svg)"
awk -v t="$TL" -v v="$VL" '
  /^```/ { f = !f }
  !f && /^!\[.*-fig-(trace|verdicts)\.svg\)$/ { next }
  { print }
  !f && $0 == "## 2. Assumptions Table" && v != "" { print ""; print v; print "" }
  !f && $0 == "## 4. Derivation Chains" && t != "" { print ""; print t; print "" }
' "$R" | cat -s > "$R.tmp" && mv "$R.tmp" "$R"
rm -f "$R.tmp"
grep -n '!\[' "$R"
